1	import { ActivatedRoute, convertToParamMap, provideRouter } from '@angular/router';
2	import { LOCALE_ID } from '@angular/core';
3	import { TestBed } from '@angular/core/testing';
4	import { registerLocaleData } from '@angular/common';
5	import localeDe from '@angular/common/locales/de';
6	import { Subject, of, throwError } from 'rxjs';
7	import { vi } from 'vitest';
8	import { VeranstaltungenService } from '../shared/api/veranstaltungen.service';
9	import { Preiskategorie } from '../shared/models/preiskategorie';
10	import { Sitzplan, SitzplanPosition, SitzplanReihe } from '../shared/models/sitzplan';
11	import { VeranstaltungDetail } from '../shared/models/veranstaltung-detail';
12	import { Buchung } from './buchung';
13	
14	registerLocaleData(localeDe);
15	
16	describe('Buchung', () => {
17	  function erzeugeVeranstaltungDetail(
18	    preiskategorien: Preiskategorie[] = [
19	      { id: 'E1-A', name: 'Kategorie A', preis: 32 },
20	      { id: 'E1-B', name: 'Kategorie B', preis: 22 },
21	    ],
22	  ): VeranstaltungDetail {
23	    return {
24	      id: 'E1',
25	      titel: 'Kammerkonzert Frühling',
26	      beschreibung: 'Ein intimes Konzert.',
27	      dauerMinuten: 90,
28	      altersfreigabe: 0,
29	      spielstaetteName: 'Stadthalle Nordpark',
30	      raumName: 'Kleiner Saal',
31	      zeitpunkt: '2026-09-05T19:30:00+02:00',
32	      preiskategorien,
33	    };
34	  }
35	
36	  function positionenFuerReihe(belegteCodes: string[], reihe: string): SitzplanPosition[] {
37	    const positionen: SitzplanPosition[] = [];
38	    for (let spalte = 1; spalte <= 10; spalte++) {
39	      if (spalte === 6) {
40	        positionen.push({ spalte, typ: 'Gang', code: null, status: null });
41	      } else {
42	        const code = `${reihe}${spalte}`;
43	        positionen.push({
44	          spalte,
45	          typ: 'Sitzplatz',
46	          code,
47	          status: belegteCodes.includes(code) ? 'Belegt' : 'Frei',
48	        });
49	      }
50	    }
51	    return positionen;
52	  }
53	
54	  function erzeugeR2Sitzplan(): Sitzplan {
55	    const belegteCodes = ['B3', 'B4', 'C7'];
56	    const reihen: SitzplanReihe[] = ['A', 'B', 'C', 'D', 'E', 'F'].map((reihe) => ({
57	      reihe,
58	      positionen: positionenFuerReihe(belegteCodes, reihe),
59	    }));
60	    return { veranstaltungId: 'E1', raumId: 'R2', raumName: 'Kleiner Saal', reihen };
61	  }
62	
63	  function seatDiv(fixture: { nativeElement: HTMLElement }, code: string): HTMLElement {
64	    return fixture.nativeElement.querySelector(`.seat-tile[title="${code}"]`)!;
65	  }
66	
67	  function createFixture(serviceStub: Pick<VeranstaltungenService, 'getSitzplan' | 'getVeranstaltung'>) {
68	    TestBed.configureTestingModule({
69	      imports: [Buchung],
70	      providers: [
71	        provideRouter([]),
72	        { provide: VeranstaltungenService, useValue: serviceStub },
73	        { provide: ActivatedRoute, useValue: { paramMap: of(convertToParamMap({ id: 'E1' })) } },
74	      ],
75	    });
76	    return TestBed.createComponent(Buchung);
77	  }
78	
79	  it('rendert an einer Gang-Position keine app-seat-tile, sondern eine sitzplan__luecke', () => {
80	    const fixture = createFixture({
81	      getSitzplan: () => of(erzeugeR2Sitzplan()),
82	      getVeranstaltung: () => of(erzeugeVeranstaltungDetail()),
83	    });
84	    fixture.detectChanges();
85	
86	    const ersteReihe: HTMLElement = fixture.nativeElement.querySelector('.sitzplan__reihe');
87	    expect(ersteReihe.querySelector('.sitzplan__luecke')).not.toBeNull();
88	    expect(ersteReihe.querySelectorAll('app-seat-tile').length).toBe(9);
89	  });
90	
91	  it('rendert für eine belegte Sitzplatz-Position eine app-seat-tile mit Status belegt', () => {
92	    const fixture = createFixture({
93	      getSitzplan: () => of(erzeugeR2Sitzplan()),
94	      getVeranstaltung: () => of(erzeugeVeranstaltungDetail()),
95	    });
96	    fixture.detectChanges();
97	
98	    const kacheln: HTMLElement[] = Array.from(
99	      fixture.nativeElement.querySelectorAll('app-seat-tile'),
100	    );
101	    const belegteKachel = kacheln.find((k) =>
102	      k.querySelector('.seat-tile')?.getAttribute('aria-label')?.includes('belegt'),
103	    );
104	    expect(belegteKachel).toBeDefined();
105	  });
106	
107	  it('rendert für die R2-Geometrie 54 app-seat-tile-Elemente und 6 sitzplan__luecke-Elemente', () => {
108	    const fixture = createFixture({
109	      getSitzplan: () => of(erzeugeR2Sitzplan()),
110	      getVeranstaltung: () => of(erzeugeVeranstaltungDetail()),
111	    });
112	    fixture.detectChanges();
113	
114	    expect(fixture.nativeElement.querySelectorAll('app-seat-tile').length).toBe(54);
115	    expect(fixture.nativeElement.querySelectorAll('.sitzplan__luecke').length).toBe(6);
116	  });
117	
118	  it('zeigt vor Auflösung den Skeleton-Container an, keine app-seat-tile', () => {
119	    const nichtAufgeloest = new Subject<Sitzplan>();
120	    const fixture = createFixture({
121	      getSitzplan: () => nichtAufgeloest.asObservable(),
122	      getVeranstaltung: () => of(erzeugeVeranstaltungDetail()),
123	    });
124	    fixture.detectChanges();
125	
126	    const container: HTMLElement = fixture.nativeElement.querySelector('.sitzplan');
127	    expect(container.getAttribute('aria-busy')).toBe('true');
128	    expect(fixture.nativeElement.querySelectorAll('app-seat-tile').length).toBe(0);
129	  });
130	
131	  it('zeigt bei fehlgeschlagenem Laden eine Fehlermeldung statt leerer Fläche', () => {
132	    const fixture = createFixture({
133	      getSitzplan: () => throwError(() => new Error('Netzwerkfehler')),
134	      getVeranstaltung: () => of(erzeugeVeranstaltungDetail()),
135	    });
136	    fixture.detectChanges();
137	
138	    expect(fixture.nativeElement.textContent).toContain('Sitzplan konnte nicht geladen werden.');
139	  });
140	
141	  it('laedt den Sitzplan bei jeder neuen Routenaktivierung frisch statt aus einem vorherigen Aufruf zwischenzuspeichern', () => {
142	    const paramMap$ = new Subject<ReturnType<typeof convertToParamMap>>();
143	    let aufrufe = 0;
144	    TestBed.configureTestingModule({
145	      imports: [Buchung],
146	      providers: [
147	        provideRouter([]),
148	        {
149	          provide: VeranstaltungenService,
150	          useValue: {
151	            getSitzplan: () => {
152	              aufrufe++;
153	              return of(erzeugeR2Sitzplan());
154	            },
155	            getVeranstaltung: () => of(erzeugeVeranstaltungDetail()),
156	          },
157	        },
158	        { provide: ActivatedRoute, useValue: { paramMap: paramMap$.asObservable() } },
159	      ],
160	    });
161	    const fixture = TestBed.createComponent(Buchung);
162	    fixture.detectChanges();
163	
164	    paramMap$.next(convertToParamMap({ id: 'E1' }));
165	    fixture.detectChanges();
166	    expect(aufrufe).toBe(1);
167	
168	    paramMap$.next(convertToParamMap({ id: 'E2' }));
169	    fixture.detectChanges();
170	    expect(aufrufe).toBe(2);
171	  });
172	
173	  it('rendert den sitzplan-Container mit horizontalem Scrollen und einer Reihenbeschriftung pro Zeile', () => {
174	    const fixture = createFixture({
175	      getSitzplan: () => of(erzeugeR2Sitzplan()),
176	      getVeranstaltung: () => of(erzeugeVeranstaltungDetail()),
177	    });
178	    fixture.detectChanges();
179	
180	    expect(fixture.nativeElement.querySelector('.sitzplan')).not.toBeNull();
181	    expect(fixture.nativeElement.querySelectorAll('.sitzplan__reihen-label').length).toBe(6);
182	  });
183	
184	  it('schaltet die Auswahl eines freien Platzes per Klick um und beim zweiten Klick wieder zurück', () => {
185	    const fixture = createFixture({
186	      getSitzplan: () => of(erzeugeR2Sitzplan()),
187	      getVeranstaltung: () => of(erzeugeVeranstaltungDetail()),
188	    });
189	    fixture.detectChanges();
190	
191	    seatDiv(fixture, 'A1').click();
192	    fixture.detectChanges();
193	    expect(seatDiv(fixture, 'A1').classList.contains('seat-tile--ausgewaehlt')).toBe(true);
194	
195	    seatDiv(fixture, 'A1').click();
196	    fixture.detectChanges();
197	    expect(seatDiv(fixture, 'A1').classList.contains('seat-tile--ausgewaehlt')).toBe(false);
198	  });
199	
200	  it('ändert bei Klick auf einen belegten Platz nichts am Auswahlzustand', () => {
201	    const fixture = createFixture({
202	      getSitzplan: () => of(erzeugeR2Sitzplan()),
203	      getVeranstaltung: () => of(erzeugeVeranstaltungDetail()),
204	    });
205	    fixture.detectChanges();
206	
207	    seatDiv(fixture, 'B3').click();
208	    fixture.detectChanges();
209	
210	    expect(seatDiv(fixture, 'B3').classList.contains('seat-tile--ausgewaehlt')).toBe(false);
211	  });
212	
213	  it('aktualisiert den Roving-Tabindex-Fokus beim Klick auf eine nicht fokussierte Kachel, sodass eine nachfolgende Pfeiltastennavigation von dort aus fortsetzt', () => {
214	    const fixture = createFixture({
215	      getSitzplan: () => of(erzeugeR2Sitzplan()),
216	      getVeranstaltung: () => of(erzeugeVeranstaltungDetail()),
217	    });
218	    fixture.detectChanges();
219	
220	    expect(seatDiv(fixture, 'A1').getAttribute('tabindex')).toBe('0');
221	
222	    seatDiv(fixture, 'A3').click();
223	    fixture.detectChanges();
224	
225	    expect(seatDiv(fixture, 'A3').getAttribute('tabindex')).toBe('0');
